SELECT * FROM "elb_logs" WHERE elb_status_code = 504 LIMIT 10000;
SELECT COUNT(*) AS error_count, histogram(_timestamp, '5 minutes') AS "span(`@timestamp`,5m)", elb_status_code FROM "elb_logs" WHERE elb_status_code >= 500 GROUP BY 2, 3 LIMIT 10000;
SELECT COUNT(*) AS "requestCount", histogram(_timestamp, '5 minutes') AS time_bin, elb_status_code FROM "elb_logs" WHERE elb_status_code IS NOT NULL GROUP BY 2, 3 ORDER BY time_bin DESC LIMIT 10000;
SELECT COUNT(*) AS requests, SUM(CASE WHEN elb_status_code >= 400 THEN 1 ELSE 0 END) AS errors, histogram(_timestamp, '1 hour') AS hour FROM "elb_logs" GROUP BY 3 ORDER BY hour ASC LIMIT 10000;
SELECT COUNT(*) AS total_requests, SUM(CASE WHEN elb_status_code > 499 THEN 1 ELSE 0 END) AS errors, ROUND(SUM(CASE WHEN elb_status_code > 499 THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 4) AS error_rate_pct FROM "elb_logs";
SELECT COUNT(*) AS "requestCount", url_path FROM "elb_logs" WHERE elb_status_code >= 500 AND url_path IS NOT NULL GROUP BY url_path ORDER BY "requestCount" DESC LIMIT 10000;
SELECT *, _timestamp / 1000 AS ts_ms FROM "elb_logs" WHERE elb_status_code >= 500 ORDER BY ts_ms DESC, trace_id ASC NULLS FIRST LIMIT 1000;
SELECT COUNT(*) AS c, elb_status_code, target_status_code FROM "elb_logs" WHERE elb_status_code IS NOT NULL AND target_status_code IS NOT NULL GROUP BY elb_status_code, target_status_code ORDER BY c DESC, elb_status_code ASC, target_status_code ASC LIMIT 10000;
SELECT COUNT(*) AS "count", client_ip FROM "elb_logs" WHERE client_ip IS NOT NULL GROUP BY client_ip ORDER BY "count" DESC LIMIT 10000;
SELECT COUNT(*) AS c, http_method, client_ip FROM "elb_logs" WHERE http_method IS NOT NULL AND client_ip IS NOT NULL GROUP BY http_method, client_ip ORDER BY c DESC, http_method ASC, client_ip ASC LIMIT 100;
SELECT COUNT(*) AS "count", client_ip, elb, request_url FROM "elb_logs" WHERE client_ip IS NOT NULL AND elb IS NOT NULL AND request_url IS NOT NULL GROUP BY client_ip, elb, request_url ORDER BY "count" DESC LIMIT 10000;
SELECT request_url, _timestamp / 1000 AS ts_ms FROM "elb_logs" WHERE user_agent LIKE '%Safari%' ORDER BY ts_ms ASC, trace_id ASC NULLS FIRST LIMIT 10;
SELECT COUNT(*) AS "scanAttempts", MIN(_timestamp) AS first_seen, MAX(_timestamp) AS last_seen, client_ip, user_agent FROM "elb_logs" WHERE (request LIKE '%.env%' OR request LIKE '%admin%' OR request LIKE '%login%' OR request LIKE '%cgi-bin%' OR request LIKE '%remote/login%' OR request LIKE '%+CSCOE+%') AND client_ip IS NOT NULL AND user_agent IS NOT NULL GROUP BY client_ip, user_agent ORDER BY "scanAttempts" DESC LIMIT 20;
SELECT COUNT(*) AS requests, approx_percentile_cont(target_processing_time, 0.99) AS latency_p99, SUM(CASE WHEN elb_status_code >= 500 THEN 1 ELSE 0 END) AS errors, user_agent, http_method, url_path FROM "elb_logs" WHERE target_processing_time > 0 AND user_agent IS NOT NULL AND http_method IS NOT NULL AND url_path IS NOT NULL GROUP BY user_agent, http_method, url_path HAVING COUNT(*) >= 10 ORDER BY latency_p99 DESC LIMIT 25;
SELECT COUNT(*) AS requests, AVG(target_processing_time) AS avg_latency, approx_percentile_cont(target_processing_time, 0.99) AS p99_latency, target_ip FROM "elb_logs" WHERE target_processing_time > 0 AND target_ip IS NOT NULL GROUP BY target_ip ORDER BY avg_latency DESC LIMIT 10000;
SELECT AVG(target_processing_time) AS avg_latency, approx_percentile_cont(target_processing_time, 0.5) AS p50, approx_percentile_cont(target_processing_time, 0.9) AS p90, approx_percentile_cont(target_processing_time, 0.99) AS p99, histogram(_timestamp, '5 minutes') AS time_bin FROM "elb_logs" WHERE target_processing_time <> -1 GROUP BY 5 ORDER BY time_bin DESC LIMIT 10000;
SELECT approx_percentile_cont(target_processing_time, 0.95) AS p95, COUNT(*) AS c, elb_status_code FROM "elb_logs" WHERE target_processing_time >= 0 AND elb_status_code IS NOT NULL GROUP BY elb_status_code ORDER BY elb_status_code ASC LIMIT 10000;
SELECT AVG(request_processing_time) AS average_request_processing_time, AVG(target_processing_time) AS average_target_processing_time, AVG(response_processing_time) AS average_response_processing_time FROM "elb_logs";
SELECT _timestamp, request_url, target_processing_time, elb_status_code, target_status_code FROM "elb_logs" WHERE target_processing_time > 5 ORDER BY target_processing_time DESC LIMIT 1000;
SELECT "@timestamp", CASE WHEN code IS NULL THEN 'NULL' WHEN series_rank <= 10 THEN CAST(code AS VARCHAR) ELSE 'OTHER' END AS elb_status_code, SUM(c) AS "count()" FROM (SELECT hour AS "@timestamp", code, c, DENSE_RANK() OVER (ORDER BY code IS NULL, series_total DESC, code ASC) AS series_rank FROM (SELECT histogram(_timestamp, '1 hour') AS hour, elb_status_code AS code, COUNT(*) AS c, SUM(COUNT(*)) OVER (PARTITION BY elb_status_code) AS series_total FROM "elb_logs" GROUP BY 1, 2)) GROUP BY 1, 2 ORDER BY 1 ASC, 2 ASC LIMIT 10000;
SELECT COUNT(DISTINCT client_ip) AS unique_clients FROM "elb_logs";
SELECT SUM(received_bytes / 1000000.0) AS client_datareceived_megabytes, client_ip FROM "elb_logs" WHERE client_ip IS NOT NULL GROUP BY client_ip ORDER BY client_datareceived_megabytes DESC LIMIT 10000;
SELECT COUNT(*) AS "requestCount", MIN(_timestamp) AS "firstLogTime", MAX(_timestamp) AS "lastLogTime", AVG(received_bytes + sent_bytes) AS "avgTransactionSize", SUM(received_bytes) AS "totalBytesReceived", SUM(sent_bytes) AS "totalBytesSent", SUM(received_bytes + sent_bytes) AS "totalBytes", elb FROM "elb_logs" WHERE elb IS NOT NULL GROUP BY elb ORDER BY "requestCount" DESC LIMIT 10;
SELECT *, _timestamp / 1000 AS ts_ms FROM "elb_logs" WHERE _timestamp >= 1790121600000000 AND _timestamp < 1790208000000000 ORDER BY ts_ms ASC, trace_id ASC NULLS FIRST LIMIT 5000;
SELECT * FROM "elb_logs" ORDER BY _timestamp ASC LIMIT 100;
SELECT COUNT(*) AS c FROM "elb_logs";
SELECT COUNT(*) AS c, client_ip, url_path FROM "elb_logs" WHERE url_path IS NOT NULL AND client_ip IS NOT NULL GROUP BY client_ip, url_path ORDER BY c DESC, client_ip ASC, url_path ASC LIMIT 10;
SELECT COUNT(*) AS c, SUM(CASE WHEN elb_status_code >= 400 THEN 1 ELSE 0 END) AS sr, AVG(received_bytes) AS arb, trace_id, client_ip FROM "elb_logs" WHERE trace_id IS NOT NULL AND client_ip IS NOT NULL GROUP BY trace_id, client_ip ORDER BY c DESC LIMIT 10;
SELECT COUNT(*) AS c, conn_trace_id, date_part('minute', to_timestamp_micros(_timestamp)) AS m, url_path FROM "elb_logs" WHERE url_path IS NOT NULL AND conn_trace_id IS NOT NULL GROUP BY 2, 3, 4 ORDER BY c DESC LIMIT 10;
SELECT COUNT(*) AS c, conn_trace_id, url_path FROM "elb_logs" WHERE url_path IS NOT NULL AND conn_trace_id IS NOT NULL GROUP BY conn_trace_id, url_path LIMIT 10;
SELECT SUM(received_bytes) AS s0, SUM(received_bytes + 1) AS s1, SUM(received_bytes + 2) AS s2, SUM(received_bytes + 3) AS s3, SUM(received_bytes + 4) AS s4, SUM(received_bytes + 5) AS s5, SUM(received_bytes + 6) AS s6, SUM(received_bytes + 7) AS s7, SUM(received_bytes + 8) AS s8, SUM(received_bytes + 9) AS s9, SUM(received_bytes + 10) AS s10, SUM(received_bytes + 11) AS s11, SUM(received_bytes + 12) AS s12, SUM(received_bytes + 13) AS s13, SUM(received_bytes + 14) AS s14, SUM(received_bytes + 15) AS s15, SUM(received_bytes + 16) AS s16, SUM(received_bytes + 17) AS s17, SUM(received_bytes + 18) AS s18, SUM(received_bytes + 19) AS s19, SUM(received_bytes + 20) AS s20, SUM(received_bytes + 21) AS s21, SUM(received_bytes + 22) AS s22, SUM(received_bytes + 23) AS s23, SUM(received_bytes + 24) AS s24, SUM(received_bytes + 25) AS s25, SUM(received_bytes + 26) AS s26, SUM(received_bytes + 27) AS s27, SUM(received_bytes + 28) AS s28, SUM(received_bytes + 29) AS s29, SUM(received_bytes + 30) AS s30, SUM(received_bytes + 31) AS s31, SUM(received_bytes + 32) AS s32, SUM(received_bytes + 33) AS s33, SUM(received_bytes + 34) AS s34, SUM(received_bytes + 35) AS s35, SUM(received_bytes + 36) AS s36, SUM(received_bytes + 37) AS s37, SUM(received_bytes + 38) AS s38, SUM(received_bytes + 39) AS s39, SUM(received_bytes + 40) AS s40, SUM(received_bytes + 41) AS s41, SUM(received_bytes + 42) AS s42, SUM(received_bytes + 43) AS s43, SUM(received_bytes + 44) AS s44, SUM(received_bytes + 45) AS s45, SUM(received_bytes + 46) AS s46, SUM(received_bytes + 47) AS s47, SUM(received_bytes + 48) AS s48, SUM(received_bytes + 49) AS s49, SUM(received_bytes + 50) AS s50, SUM(received_bytes + 51) AS s51, SUM(received_bytes + 52) AS s52, SUM(received_bytes + 53) AS s53, SUM(received_bytes + 54) AS s54, SUM(received_bytes + 55) AS s55, SUM(received_bytes + 56) AS s56, SUM(received_bytes + 57) AS s57, SUM(received_bytes + 58) AS s58, SUM(received_bytes + 59) AS s59, SUM(received_bytes + 60) AS s60, SUM(received_bytes + 61) AS s61, SUM(received_bytes + 62) AS s62, SUM(received_bytes + 63) AS s63, SUM(received_bytes + 64) AS s64, SUM(received_bytes + 65) AS s65, SUM(received_bytes + 66) AS s66, SUM(received_bytes + 67) AS s67, SUM(received_bytes + 68) AS s68, SUM(received_bytes + 69) AS s69, SUM(received_bytes + 70) AS s70, SUM(received_bytes + 71) AS s71, SUM(received_bytes + 72) AS s72, SUM(received_bytes + 73) AS s73, SUM(received_bytes + 74) AS s74, SUM(received_bytes + 75) AS s75, SUM(received_bytes + 76) AS s76, SUM(received_bytes + 77) AS s77, SUM(received_bytes + 78) AS s78, SUM(received_bytes + 79) AS s79, SUM(received_bytes + 80) AS s80, SUM(received_bytes + 81) AS s81, SUM(received_bytes + 82) AS s82, SUM(received_bytes + 83) AS s83, SUM(received_bytes + 84) AS s84, SUM(received_bytes + 85) AS s85, SUM(received_bytes + 86) AS s86, SUM(received_bytes + 87) AS s87, SUM(received_bytes + 88) AS s88, SUM(received_bytes + 89) AS s89 FROM "elb_logs";
SELECT COUNT(*) AS n, type, elb, target_port, elb_status_code, target_status_code, http_method, http_version, ssl_cipher, ssl_protocol, target_group_arn FROM "elb_logs" WHERE type IS NOT NULL AND elb IS NOT NULL AND target_port IS NOT NULL AND elb_status_code IS NOT NULL AND target_status_code IS NOT NULL AND http_method IS NOT NULL AND http_version IS NOT NULL AND ssl_cipher IS NOT NULL AND ssl_protocol IS NOT NULL AND target_group_arn IS NOT NULL GROUP BY type, elb, target_port, elb_status_code, target_status_code, http_method, http_version, ssl_cipher, ssl_protocol, target_group_arn ORDER BY n DESC, type ASC, elb ASC, target_port ASC, elb_status_code ASC, target_status_code ASC, http_method ASC, http_version ASC, ssl_cipher ASC, ssl_protocol ASC, target_group_arn ASC LIMIT 10;
SELECT COUNT(*) AS n, type, elb, target_port, elb_status_code, target_status_code, http_method, http_version, ssl_cipher, ssl_protocol, target_group_arn, chosen_cert_arn, matched_rule_priority, actions_executed, target_status_code_list, classification, classification_reason, lb_node_ip, domain_name, url_host, target_ip FROM "elb_logs" WHERE type IS NOT NULL AND elb IS NOT NULL AND target_port IS NOT NULL AND elb_status_code IS NOT NULL AND target_status_code IS NOT NULL AND http_method IS NOT NULL AND http_version IS NOT NULL AND ssl_cipher IS NOT NULL AND ssl_protocol IS NOT NULL AND target_group_arn IS NOT NULL AND chosen_cert_arn IS NOT NULL AND matched_rule_priority IS NOT NULL AND actions_executed IS NOT NULL AND target_status_code_list IS NOT NULL AND classification IS NOT NULL AND classification_reason IS NOT NULL AND lb_node_ip IS NOT NULL AND domain_name IS NOT NULL AND url_host IS NOT NULL AND target_ip IS NOT NULL GROUP BY type, elb, target_port, elb_status_code, target_status_code, http_method, http_version, ssl_cipher, ssl_protocol, target_group_arn, chosen_cert_arn, matched_rule_priority, actions_executed, target_status_code_list, classification, classification_reason, lb_node_ip, domain_name, url_host, target_ip ORDER BY n DESC, type ASC, elb ASC, target_port ASC, elb_status_code ASC, target_status_code ASC, http_method ASC, http_version ASC, ssl_cipher ASC, ssl_protocol ASC, target_group_arn ASC, chosen_cert_arn ASC, matched_rule_priority ASC, actions_executed ASC, target_status_code_list ASC, classification ASC, classification_reason ASC, lb_node_ip ASC, domain_name ASC, url_host ASC, target_ip ASC LIMIT 5;
SELECT COUNT(*) AS pv, received_bytes, sent_bytes FROM "elb_logs" WHERE http_method = 'POST' AND _timestamp >= 1789689600000000 AND _timestamp < 1790553599001000 AND elb_status_code = 200 AND url_path = '/_bulk' AND received_bytes IS NOT NULL AND sent_bytes IS NOT NULL GROUP BY received_bytes, sent_bytes ORDER BY pv DESC LIMIT 10 OFFSET 10000;
SELECT COUNT(*) AS c FROM "elb_logs" WHERE regexp_like(url_path, '[.](env|git|php)([.]|$)');
SELECT COUNT(*) AS c, regexp_match(url_path, '[.]([A-Za-z0-9]+)$')[1] AS ext FROM "elb_logs" WHERE url_path IS NOT NULL AND regexp_like(url_path, '[.][A-Za-z0-9]+$') GROUP BY 2 ORDER BY c DESC, ext ASC LIMIT 10;
SELECT http_method, elb_status_code, first_value(_timestamp ORDER BY _timestamp / 1000 DESC, trace_id ASC NULLS FIRST) AS "@timestamp", first_value(trace_id ORDER BY _timestamp / 1000 DESC, trace_id ASC NULLS FIRST) AS trace_id FROM "elb_logs" WHERE http_method IS NOT NULL AND elb_status_code IS NOT NULL GROUP BY http_method, elb_status_code ORDER BY http_method ASC, elb_status_code ASC LIMIT 10000;
SELECT COUNT(*) AS c FROM "elb_logs" WHERE client_port = 2829;
